text='\n'.join(lines)+'\n'
text=text.replace('448 separate physical solids','448 separate modeled material solids (including adhesive volumes; not448 manufactured stock pieces)').replace('New-part overlap findings above0.001 mm³','Hard-part interference findings')
for a,b in [('assumed2','assumed 2'),('assumed70','assumed 70'),('with50%','with 50%'),('below0.02','below 0.02'),('the52 g','the 52 g'),('proposed8 mm','proposed 8 mm'),('have8 mm','have 8 mm'),('are6.1 mm','are 6.1 mm'),('and5.7 mm','and 5.7 mm'),('are8 mm','are 8 mm'),('versus the inherited assumed2','versus the inherited assumed 2'),('not448','not 448')]:text=text.replace(a,b)
