page='<!doctype html><meta charset="utf-8"><title>RescU P07 wing integration review</title><style>body{font:16px/1.5 system-ui;max-width:1100px;margin:35px auto;padding:0 22px;color:#243747}pre{white-space:pre-wrap;font:inherit}img{width:100%;height:auto}a{color:#245f94}</style><h1>RescU P07 wing integration</h1><img src="../cad/P07_Wing_Cutaway.png" alt="Actual CAD carrier cutaway and rib section"><pre>'+html.escape(text)+'</pre>'
(R/'reports/REVIEW.html').write_text(page,encoding='utf8')
readme='# P07 wing-arm integration candidate\n\nStart with [the review](reports/REVIEW.md) and [construction assumptions](docs/DESIGN_AND_BUILD.md). The native assembly and STEP files are under cad/. Open the carrier-cutaway STEP to see the connection without opaque wing skins or foam. Individual new laminate regions are under cad/parts/.\n\nProvisional structural budget: **'+f"{m['structural_budget_kg']*1000:.3f} g ({r['structural_delta_kg']*1000:+.3f} g from P06)."+' The200 g reserve is separate. This is a geometric/sizing candidate, not a fabrication or flight release.\n\nSTEP preserves placed separate solids; native FreeCAD constraints do not become SolidWorks mates. See reports/step_validation.json for any thin-shell reference quantity limitations.\n\nRebuild with FreeCAD1.1 Python: tools/build_wing.py, tools/refine_layers.py, tools/check_export_account.py, tools/check_splices.py, tools/render_wing.py, tools/write_review.py. Run in that order. The source P04/P06 native documents and P05/P06 accounting files are required in the sibling study folders (P04 may be the repository root). Sources remain unchanged. Inputs document assumptions; geometry dimensions are set in the build script.\n'
readme=readme.replace('tools/refine_layers.py, tools/check_export_account.py, tools/check_splices.py, tools/render_wing.py, tools/write_review.py','tools/refine_layers.py, tools/finish_bonds.py, tools/check_export_account.py --prepare-only, tools/relieve_slot_spar.py, tools/route_wires.py, tools/check_export_account.py --fit-only, tools/run_stage.py export, tools/run_stage.py mass, tools/check_splices.py, tools/audit_patch_extents.py, tools/render_wing.py, tools/write_review.py')
readme+='\n**Critical sizing finding:** the conservative all-torque-to-spar radial edge-transfer screen fails. This revision needs a larger developed joint or a substantiated alternative load path before fabrication. See the review; no overall structural pass is claimed.\n\nThe FreeCAD display macro cad/Open_P07_Wing.FCMacro shows transparent skins, hidden foam and proposed wire bundle envelopes without saving changes.\n'
readme=readme.replace('The200 g','The 200 g').replace('FreeCAD1.1','FreeCAD 1.1')
(R/'README.md').write_text(readme,encoding='utf8')
files=[]
for p in sorted(R.rglob('*')):
 if not p.is_file() or p.suffix.lower() not in ['.fcstd','.step','.png','.json','.csv','.md','.html','.py','.fcmacro']:continue
 if 'checkpoint' in p.name or p.name in ['ARTIFACT_MANIFEST.json','prepare_resume.py']:continue
 files.append(dict(path=p.relative_to(R).as_posix(),size_bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
(R/'cad/ARTIFACT_MANIFEST.json').write_text(json.dumps(dict(version=r['version'],status=r['status'],files=files),indent=2))
def archive(path,paths):
 with zipfile.ZipFile(path,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
  for p in paths:z.write(p,p.relative_to(R).as_posix())
 with zipfile.ZipFile(path) as z:assert z.testzip() is None
archive(R/'RescU_P07_STEP_Package.zip',[p for p in R.rglob('*') if p.is_file() and (p.suffix.lower()=='.step' or p.name in ['README.md','REVIEW.md','step_validation.json','ARTIFACT_MANIFEST.json','P07_Wing_Cutaway.png'])])
archive(R/'RescU_P07_Native_CAD.zip',[R/'cad/RescU_P07_Wing_Arm_Integration.FCStd',R/'cad/Open_P07_Wing.FCMacro',R/'cad/ARTIFACT_MANIFEST.json',R/'README.md'])
archive(R/'RescU_P07_Review_Package.zip',[R/f['path'] for f in files]+[R/'cad/ARTIFACT_MANIFEST.json'])
print(json.dumps(dict(structural_g=m['structural_budget_kg']*1000,delta_g=r['structural_delta_kg']*1000,files=len(files),step_exports=len(steps),thin_shell_step_deviations=len(deviations)),indent=2))
